public boolean execute(ContainerLoader container){
  this.container=container;
  this.report=new Report();
  Progress.start(progress);
  try {
    XMLInputFactory inputFactory=XMLInputFactory.newInstance();
    if (inputFactory.isPropertySupported("javax.xml.stream.isValidating")) {
      inputFactory.setProperty("javax.xml.stream.isValidating",Boolean.FALSE);
    }
    inputFactory.setXMLReporter(new XMLReporter(){
      @Override public void report(String message, String errorType, Object relatedInformation, Location location) throws XMLStreamException {
        System.out.println("Error:" + errorType + ", message : "+ message);
      }
    });
    xmlReader=inputFactory.createXMLStreamReader(reader);
    while (xmlReader.hasNext()) {
      Integer eventType=xmlReader.next();
      if (eventType.equals(XMLEvent.START_ELEMENT)) {
        if (NODE.equalsIgnoreCase(xmlReader.getLocalName())) {
          readNode(xmlReader);
        } else if (EDGE.equalsIgnoreCase(xmlReader.getLocalName())) {
          readEdge(xmlReader);
        } else if (ATTRIBUTES.equalsIgnoreCase(xmlReader.getLocalName())) {
          readAttributes(xmlReader);
        }
      }
    }
    xmlReader.close();
  } catch (FactoryConfigurationError e) {
    System.err.println("Failed to configure XMLInputFactory: " + e.getMessage());
    throw new RuntimeException(e);
  } catch (Exception e) {
    if (e instanceof RuntimeException) {
      throw (RuntimeException)e;
    }
    throw new RuntimeException(e);
  }
  Progress.finish(progress);
  return !cancel;
}
